[CmdletBinding()] param()
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '..\windows\DeploymentJournal.ps1')
$root=Join-Path ([IO.Path]::GetTempPath()) ("boecl-journal-{0}" -f [guid]::NewGuid().ToString('N'))
try {$started=[datetimeoffset]::UtcNow.AddSeconds(-5);Write-BoeclDeploymentJournal -Environment Staging -Component Web -Status RolledBack -DeploymentId 'test-release' -Commit 'abc123' -Message "token=must-not-leak`nhealth failed" -StartedAt $started -JournalRoot $root;$snapshot=Get-Content -Raw -LiteralPath (Join-Path $root 'latest-staging-web.json')|ConvertFrom-Json;$history=Get-Content -Raw -LiteralPath (Join-Path $root 'deployment-test-release.json')|ConvertFrom-Json;if($snapshot.Status-ne'RolledBack'-or$snapshot.Commit-ne'abc123'-or$history.Status-ne'RolledBack'){throw 'Deployment snapshot and history fields were not persisted.'};if($snapshot.Message-match'must-not-leak'-or$snapshot.Message-match"`n"){throw 'Deployment message was not sanitized.'};if($snapshot.DurationSeconds-lt 4-or$snapshot.SchemaVersion-ne 2){throw 'Deployment duration or schema was not recorded.'};foreach($scriptName in @('Deploy-NextWebRelease.ps1','Deploy-AspNetApiRelease.ps1')){$script=Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot "..\windows\$scriptName");if($script-notmatch '\$terminalRecorded = \$false'-or$script-notmatch '-Status Failed'-or$script-notmatch 'if \(-not \$terminalRecorded\)'){throw "$scriptName does not persist terminal pre-swap failures."};if($scriptName-eq'Deploy-AspNetApiRelease.ps1'-and($script-notmatch'\$poolState'-or$script-notmatch'Application pool did not stop')){throw 'API deploy does not safely handle an already stopped application pool.'}};Write-Host 'Deployment journal regression tests passed.'}finally{Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue}
